registration.scalars:
//! Scalar functions exposed by the evtx worker, registered under `evtx.main`.

mod inspect;

use vgi::Worker;

/// Register every scalar function on the worker.
pub fn register(worker: &mut Worker) {
    worker.register_scalar(inspect::EvtxRecordCount);
    worker.register_scalar(inspect::IsValidEvtx);
}

registration.table_functions:
//! Table functions exposed by the evtx worker, registered under `evtx.main`.

mod evtx_records;

use vgi::Worker;

/// Register every table function on the worker.
pub fn register(worker: &mut Worker) {
    // Two overloads of the same name so the DuckDB binder accepts both a BLOB
    // (inline bytes) and a VARCHAR (path) input — it does not implicitly cast
    // between them for a table-function argument.
    worker.register_table(evtx_records::EvtxRecords::blob());
    worker.register_table(evtx_records::EvtxRecords::path());
}

registration.catalog_tail:
            views: vec![event_id_reference_view()],
            macros: Vec::new(),
            tables: Vec::new(),
        }],
        ..Default::default()
    }
}

/// The catalog name DuckDB sees in `ATTACH 'evtx' (TYPE vgi, …)`. Defaults to
/// `evtx`, but honors an explicit override so a test harness can rename it. Also
/// exports the variable so downstream SDK code observes the same default.
pub fn catalog_name() -> String {
    if std::env::var_os("VGI_WORKER_CATALOG_NAME").is_none() {
        std::env::set_var("VGI_WORKER_CATALOG_NAME", "evtx");
    }
    std::env::var("VGI_WORKER_CATALOG_NAME").unwrap_or_else(|_| "evtx".to_string())
}

/// Build a fully-registered worker: every scalar and table function plus the
/// catalog metadata. Callers choose the transport — `run()` natively (the
/// binary), `serve_reader_writer()` in the browser (the wasm crate).
pub fn build_worker() -> Worker {
    let name = catalog_name();
    let mut worker = Worker::new();
    scalar::register(&mut worker);
    table::register(&mut worker);
    worker.set_catalog(catalog_metadata(&name));
    worker
}

